/**
 * @brief Create a new automaton
 *
 * @param type The type of automaton to create (NFA or DFA)
 * @return A new automaton or NULL on failure
 */
rift_regex_automaton_t *
rift_automaton_create(rift_automaton_type_t type)
{
    rift_regex_automaton_t *automaton =
        (rift_regex_automaton_t *)calloc(1, sizeof(rift_regex_automaton_t));
    if (!automaton) {
        return NULL;
    }

    // Initialize the automaton structure
    automaton->type = type;
    automaton->is_deterministic = (type == RIFT_AUTOMATON_DFA);
    automaton->num_states = 0;
    automaton->state_capacity = AUTOMATON_INITIAL_CAPACITY;
    automaton->states =
        (rift_regex_state_t **)calloc(automaton->state_capacity, sizeof(rift_regex_state_t *));

    if (!automaton->states) {
        free(automaton);
        return NULL;
    }

    automaton->initial_state = NULL;
    automaton->current_state = NULL;
    automaton->flags = RIFT_REGEX_FLAG_NONE;
    automaton->last_error.code = RIFT_REGEX_ERROR_NONE;
    automaton->last_error.message[0] = '\0';

    return automaton;
}

bool
rift_automaton_create_transition(rift_regex_automaton_t *automaton, rift_regex_state_t *from_state,
                                 rift_regex_state_t *to_state, const char *pattern)
{
    if (!automaton || !from_state || !to_state) {
        return false;
    }

    // Allocate memory for the new transition
    rift_regex_transition_t *transition =
        (rift_regex_transition_t *)rift_malloc(sizeof(*transition));
    if (!transition) {
        return false;
    }

    // Initialize the transition
    transition->from_state = from_state;
    transition->to_state = to_state;

    // Add the transition to the automaton
    if (!rift_automaton_add_transition(automaton, from_state, to_state, pattern)) {
        rift_free(transition);
        return false;
    }

    return true;
}

