/**
 * @brief Ensures the automaton's states array has sufficient capacity
 *
 * @param automaton The automaton to modify
 * @param capacity The minimum capacity required
 * @return bool True if successful, false on allocation failure
 */
bool
rift_automaton_ensure_state_capacity(rift_regex_automaton_t *automaton, size_t capacity)
{
    if (!automaton) {
        return false;
    }

    if (automaton->state_capacity >= capacity) {
        return true; // Already has sufficient capacity
    }

    // Double the capacity until it meets the requirement
    size_t new_capacity = automaton->state_capacity;
    while (new_capacity < capacity) {
        new_capacity *= 2;
    }

    // Reallocate the states array
    rift_regex_state_t **new_states = (rift_regex_state_t **)realloc(
        automaton->states, new_capacity * sizeof(rift_regex_state_t *));

    if (!new_states) {
        return false;
    }

    // Initialize the new portion of the array to NULL
    for (size_t i = automaton->state_capacity; i < new_capacity; i++) {
        new_states[i] = NULL;
    }

    automaton->states = new_states;
    automaton->state_capacity = new_capacity;
    return true;
}

