/**
 * @brief Internal function to add a state to an automaton
 *
 * This function is called by rift_automaton_create_state
 *
 * @param automaton The automaton to add the state to
 * @param state The state to add
 * @return true if successful, false otherwise
 */
bool
rift_automaton_add_state_internal(rift_regex_automaton_t *automaton, rift_regex_state_t *state)
{
    if (!automaton || !state) {
        return false;
    }

    // Ensure there is enough capacity
    if (!rift_automaton_ensure_state_capacity(automaton, automaton->num_states + 1)) {
        return false;
    }

    // Add the state to the automaton
    automaton->states[automaton->num_states] = state;
    automaton->num_states++;

    return true;
}

