/**
 * @brief Create a new state in an automaton
 *
 * @param automaton The automaton to add the state to
 * @param is_accepting Whether the state is accepting
 * @return The new state or NULL on failure
 */
rift_regex_state_t *
rift_automaton_create_state(struct rift_regex_automaton *automaton, bool is_accepting)
{
    if (!automaton) {
        return NULL;
    }

    // Create a new state
    rift_regex_state_t *state = rift_state_create(is_accepting);
    if (!state) {
        return NULL;
    }

    // Ensure the automaton has enough capacity for the new state
    if (automaton->num_states >= automaton->state_capacity) {
        size_t new_capacity = automaton->state_capacity == 0 ? 4 : automaton->state_capacity * 2;
        rift_regex_state_t **new_states = (rift_regex_state_t **)realloc(
            automaton->states, sizeof(rift_regex_state_t *) * new_capacity);
        if (!new_states) {
            rift_state_free(state);
            return NULL;
        }
        automaton->states = new_states;
        automaton->state_capacity = new_capacity;
    }

    // Add the state to the automaton
    automaton->states[automaton->num_states++] = state;

    // If this is the first state, make it the initial state
    if (automaton->num_states == 1 && !automaton->initial_state) {
        automaton->initial_state = state;
        automaton->current_state = state;
    }

    return state;
}

