/**
 * @brief Get the number of states in an automaton
 *
 * @param automaton The automaton
 * @return The number of states
 */
size_t
rift_automaton_get_state_count(const rift_regex_automaton_t *automaton)
{
    if (!automaton) {
        return 0;
    }
    return automaton->num_states;
}

