/**
 * @brief Reset an automaton to its initial state
 *
 * @param automaton The automaton to reset
 */
void
rift_automaton_reset(rift_regex_automaton_t *automaton)
{
    if (!automaton) {
        return;
    }
    automaton->current_state = automaton->initial_state;
}

