/**
 * @brief Set a state as accepting or non-accepting
 *
 * @param automaton The automaton
 * @param state The state to modify
 * @param is_accepting Whether the state should be accepting
 * @return true if successful, false otherwise
 */
bool
rift_automaton_set_state_accepting(rift_regex_automaton_t *automaton, rift_regex_state_t *state,
                                   bool is_accepting)
{
    if (!automaton || !state) {
        return false;
    }

    // Set the state as accepting or non-accepting
    rift_state_set_accepting(state, is_accepting);
    return true;
}
