/**
 * @brief Partition states for Hopcroft's algorithm
 *
 * @param dfa The DFA to partition
 * @param partitions Array of partitions
 * @param partition_sizes Array of partition sizes
 * @param num_partitions Pointer to store the number of partitions
 * @return true if successful, false otherwise
 */
static bool
partition_states(const rift_regex_automaton_t *dfa, rift_regex_state_t ***partitions,
                 size_t *partition_sizes, size_t *num_partitions)
{
    if (!dfa || !partitions || !partition_sizes || !num_partitions) {
        return false;
    }

    // Initially partition states into accepting and non-accepting states
    size_t accepting_count = 0;
    size_t non_accepting_count = 0;

    // Count accepting and non-accepting states
    for (size_t i = 0; i < dfa->num_states; i++) {
        if (rift_state_is_accepting(dfa->states[i])) {
            accepting_count++;
        } else {
            non_accepting_count++;
        }
    }

    // Allocate partitions
    partitions[0] = (rift_regex_state_t **)malloc(accepting_count * sizeof(rift_regex_state_t *));
    partitions[1] =
        (rift_regex_state_t **)malloc(non_accepting_count * sizeof(rift_regex_state_t *));

    if (!partitions[0] || !partitions[1]) {
        free(partitions[0]);
        free(partitions[1]);
        return false;
    }

    // Initialize partition sizes
    partition_sizes[0] = 0;
    partition_sizes[1] = 0;

    // Assign states to partitions
    for (size_t i = 0; i < dfa->num_states; i++) {
        if (rift_state_is_accepting(dfa->states[i])) {
            partitions[0][partition_sizes[0]++] = dfa->states[i];
        } else {
            partitions[1][partition_sizes[1]++] = dfa->states[i];
        }
    }

    // Set the number of partitions
    *num_partitions = 2;

    return true;
}

