/**
 * @brief Find the partition containing a state
 *
 * @param state The state to find
 * @param partitions Array of partitions
 * @param partition_sizes Array of partition sizes
 * @param num_partitions Number of partitions
 * @return The index of the partition or -1 if not found
 */
static int
find_partition(const rift_regex_state_t *state, rift_regex_state_t ***partitions,
               size_t *partition_sizes, size_t num_partitions)
{
    for (size_t i = 0; i < num_partitions; i++) {
        for (size_t j = 0; j < partition_sizes[i]; j++) {
            if (partitions[i][j] == state) {
                return (int)i;
            }
        }
    }
    return -1;
}

