/**
 * @brief Check if states transition to states in the same partition
 *
 * @param state1 The first state
 * @param state2 The second state
 * @param partitions Array of partitions
 * @param partition_sizes Array of partition sizes
 * @param num_partitions Number of partitions
 * @return true if equivalent, false otherwise
 */

static bool
are_equivalent_states(const rift_regex_state_t *state1, const rift_regex_state_t *state2,
                      rift_regex_state_t ***partitions, size_t *partition_sizes,
                      size_t num_partitions)
{

    if (!state1 || !state2 || !partitions || !partition_sizes || num_partitions == 0) {
        return false;
    }

    // For each input symbol, check if the two states transition to states in the same partition
    // For simplicity, we'll use ASCII characters 0-127
    for (int c = 0; c < 128; c++) {
        size_t num_transitions1 = rift_state_get_transition_count(state1);
        size_t num_transitions2 = rift_state_get_transition_count(state2);

        // Find targets for state1
        rift_regex_state_t *target1 = NULL;
        for (size_t i = 0; i < num_transitions1; i++) {
            rift_regex_transition_t *transition = rift_state_get_transition(state1, i);
            if (!transition || rift_transition_is_epsilon(transition)) {
                continue;
            }

            if (rift_transition_matches_char(transition, (char)c)) {
                target1 = rift_transition_get_target(transition);
                break;
            }
        }

        // Find targets for state2
        rift_regex_state_t *target2 = NULL;
        for (size_t i = 0; i < num_transitions2; i++) {
            rift_regex_transition_t *transition = rift_state_get_transition(state2, i);
            if (!transition || rift_transition_is_epsilon(transition)) {
                continue;
            }

            if (rift_transition_matches_char(transition, (char)c)) {
                target2 = rift_transition_get_target(transition);
                break;
            }
        }

        // If one has a transition and the other doesn't, they're not equivalent
        if ((target1 && !target2) || (!target1 && target2)) {
            return false;
        }

        // If both have transitions, check if they go to the same partition
        if (target1 && target2) {
            int partition1 = find_partition(target1, partitions, partition_sizes, num_partitions);
            int partition2 = find_partition(target2, partitions, partition_sizes, num_partitions);

            if (partition1 != partition2) {
                return false;
            }
        }
    }
    return true;
}

