/**
 * @brief Free resources associated with an automaton
 *
 * @param automaton The automaton to free
 */
void
rift_automaton_free(rift_regex_automaton_t *automaton)
{
    if (!automaton) {
        return;
    }

    // Free each state in the automaton
    for (size_t i = 0; i < automaton->num_states; i++) {
        rift_state_free(automaton->states[i]);
    }

    // Free the states array
    free(automaton->states);

    // No need to free error message since it's an array, not dynamically allocated

    // Free the automaton structure itself
    free(automaton);
}
